// Arma el mail de alerta. Un aviso por workflow cada 30 minutos como máximo,
// para que una falla repetida no llene la casilla.
const e  = $input.first().json;
const wf = e.workflow || {};
const ex = e.execution || {};
const est = $getWorkflowStaticData('global');
est.ultimos = est.ultimos || {};
const k = String(wf.id || wf.name || 'desconocido');
const ahora = Date.now();
if (est.ultimos[k] && ahora - est.ultimos[k] < 30 * 60 * 1000) return [];
est.ultimos[k] = ahora;
const err  = ex.error || e.trigger?.error || {};
const msg  = String(err.message || err.description || 'sin detalle').slice(0, 600);
const nodo = ex.lastNodeExecuted || err.node?.name || '?';
return [{ json: {
  asunto: `[Tratto] Falló "${wf.name || k}"`,
  texto: `Workflow: ${wf.name} (${wf.id})\nNodo: ${nodo}\nError: ${msg}\nEjecución: ${ex.url || ex.id || '?'}\nHora: ${new Date().toISOString()}\n\n` +
         `No se manda otro aviso de este workflow por 30 minutos. Qué hacer: docs/MONITORING.md en el repositorio.`
} }];
